import sys, json

class Solution:
    def twoSum(self, nums, target):
        seen = {}
        for i, v in enumerate(nums):
            comp = target - v
            if comp in seen:
                return [seen[comp], i]
            seen[v] = i

if __name__ == '__main__':
    args = json.loads(sys.stdin.readline())
    nums, target = args[0], args[1]
    print(json.dumps(Solution().twoSum(nums, target)))

